def encode(value):
    if isinstance(value, datetime): return value.isoformat()
    if isinstance(value, bytes): return {'base64': base64.b64encode(value).decode()}
    raise TypeError(type(value).__name__)

def save():
    OUT.write_text(json.dumps(DATA, default=encode, indent=2) + '\n')

def call(service, operation, label, cleanup=False, **params):
    record = {'label': label, 'at': datetime.now(timezone.utc).isoformat(), 'service': service, 'operation': operation, 'request': params}
    try:
        response = getattr(CLIENTS[service], operation)(**params)
        if 'Body' in response and hasattr(response['Body'], 'read'):
            body = response['Body'].read()
            response['Body'].close()
            response['Body'] = {'base64': base64.b64encode(body).decode(), 'utf8': body.decode('utf-8', errors='strict'), 'size': len(body), 'sha256': hashlib.sha256(body).hexdigest()}
        record['response'] = response
    except ClientError as exc:
        record['error'] = exc.response
    except Exception as exc:
        record['transport_error'] = {'type': type(exc).__name__, 'message': str(exc)}
    DATA['cleanup' if cleanup else 'observations'].append(record)
    save()
    return record

def required(record):
    if 'response' not in record: raise RuntimeError('Required operation failed: ' + record['label'])
    return record['response']

