def snapshot(name, parent, phase, detailed=False):
    maps = call('stepfunctions', 'list_map_runs', name + ':' + phase + ':list_maps', executionArn=parent, maxResults=100)
    run_snapshot = {'phase': phase, 'at': datetime.now(timezone.utc).isoformat(), 'mapRuns': []}
    for entry in maps.get('response', {}).get('mapRuns', []):
        arn = entry['mapRunArn']
        desc = call('stepfunctions', 'describe_map_run', name + ':' + phase + ':map', mapRunArn=arn)
        listed = call('stepfunctions', 'list_executions', name + ':' + phase + ':children', mapRunArn=arn, maxResults=100)
        members = listed.get('response', {}).get('executions', [])
        run_snapshot['mapRuns'].append({'mapRunArn': arn, 'describe': desc.get('response', desc.get('error')), 'members': members})
        for child in members:
            child_arn = child['executionArn']
            CHILDREN.add(child_arn)
            if detailed:
                call('stepfunctions', 'describe_execution', name + ':' + phase + ':child_describe', executionArn=child_arn)
                call('stepfunctions', 'get_execution_history', name + ':' + phase + ':child_history', executionArn=child_arn, maxResults=100, includeExecutionData=True)
                call('stepfunctions', 'describe_state_machine_for_execution', name + ':' + phase + ':child_definition', executionArn=child_arn, includedData='ALL_DATA')
        if detailed:
            for status in ('RUNNING', 'SUCCEEDED', 'FAILED', 'ABORTED'):
                call('stepfunctions', 'list_executions', name + ':' + phase + ':filter_' + status, mapRunArn=arn, statusFilter=status, maxResults=100)
    DATA['runs'][name]['snapshots'].append(run_snapshot)
    save()
    return run_snapshot

def run_case(name, machine, payload, reserved, initial_detail=False):
    global BUDGET_RESERVED
    if BUDGET_RESERVED + reserved > 24: raise RuntimeError('Execution reservation exceeds 24')
    BUDGET_RESERVED += reserved
    DATA['execution_budget_reserved'] = BUDGET_RESERVED
    DATA['runs'][name] = {'machine': machine, 'input': payload, 'reserved_parent_and_children': reserved, 'snapshots': []}
    response = required(call('stepfunctions', 'start_execution', name + ':start', stateMachineArn=ARNS[machine], name=name + '-' + uuid.uuid4().hex[:8], input=json.dumps(payload)))
    arn = response['executionArn']
    PARENTS.append(arn)
    DATA['owned_resources']['executions'].append(arn)
    DATA['runs'][name]['executionArn'] = arn
    snapshot(name, arn, 'immediate')
    time.sleep(2)
    snapshot(name, arn, 'early', detailed=initial_detail)
    if initial_detail:
        call('stepfunctions', 'list_executions', name + ':early:machine_members', stateMachineArn=ARNS[machine], maxResults=100)
        call('stepfunctions', 'get_execution_history', name + ':early:parent_history', executionArn=arn, maxResults=100, includeExecutionData=True)
    terminal = None
    for attempt in range(55):
        description = call('stepfunctions', 'describe_execution', name + ':poll:' + str(attempt), executionArn=arn)
        if description.get('response', {}).get('status') in TERMINAL:
            terminal = description['response']
            break
        time.sleep(2)
        if attempt in (3, 9): snapshot(name, arn, 'mid-' + str(attempt))
    if terminal is None: raise RuntimeError('Execution exceeded bounded observation window: ' + name)
    DATA['runs'][name]['terminal'] = terminal
    snapshot(name, arn, 'terminal', detailed=True)
    call('stepfunctions', 'get_execution_history', name + ':terminal:parent_history', executionArn=arn, maxResults=100, includeExecutionData=True)
    call('stepfunctions', 'list_executions', name + ':terminal:machine_members', stateMachineArn=ARNS[machine], maxResults=100)
    time.sleep(3)
    snapshot(name, arn, 'settled')
    download_objects(name)
    DATA['execution_count_observed'] = {'parents': len(PARENTS), 'children': len(CHILDREN), 'total': len(PARENTS) + len(CHILDREN)}
    save()
    print(json.dumps({'case': name, 'terminal': terminal['status'], 'counts': DATA['execution_count_observed'], 'snapshot': DATA['runs'][name]['snapshots'][-1]}, default=encode), flush=True)

def download_objects(label):
    listed = call('s3', 'list_objects_v2', label + ':objects', Bucket=BUCKET, Prefix='results/')
    seen = {record.get('request', {}).get('Key') for record in DATA['observations'] if record['operation'] == 'get_object'}
    for item in listed.get('response', {}).get('Contents', []):
        if item['Key'] not in seen:
            call('s3', 'get_object', label + ':download', Bucket=BUCKET, Key=item['Key'])

def cleanup():
    all_terminal = True
    for arn in PARENTS:
        desc = call('stepfunctions', 'describe_execution', 'cleanup:parent_status', cleanup=True, executionArn=arn)
        if desc.get('response', {}).get('status') == 'RUNNING':
            call('stepfunctions', 'stop_execution', 'cleanup:stop_parent', cleanup=True, executionArn=arn, error='OwnedProbeCleanup', cause='bounded native probe cleanup')
    for attempt in range(35):
        running = []
        for arn in PARENTS:
            desc = call('stepfunctions', 'describe_execution', 'cleanup:wait_parent', cleanup=True, executionArn=arn)
            if desc.get('response', {}).get('status') not in TERMINAL: running.append(arn)
            maps = call('stepfunctions', 'list_map_runs', 'cleanup:map_membership', cleanup=True, executionArn=arn, maxResults=100)
            for entry in maps.get('response', {}).get('mapRuns', []):
                listed = call('stepfunctions', 'list_executions', 'cleanup:child_membership', cleanup=True, mapRunArn=entry['mapRunArn'], maxResults=100)
                for child in listed.get('response', {}).get('executions', []):
                    CHILDREN.add(child['executionArn'])
                    if child['status'] == 'RUNNING':
                        running.append(child['executionArn'])
                        call('stepfunctions', 'stop_execution', 'cleanup:stop_child', cleanup=True, executionArn=child['executionArn'], error='OwnedProbeCleanup')
        if not running: break
        time.sleep(2)
    else:
        all_terminal = False
        DATA['notes'].append('Cleanup cannot assert every execution terminal after bounded wait.')
    DATA['cleanup_all_executions_terminal'] = all_terminal
    for machine in CREATED['machines']:
        call('stepfunctions', 'delete_state_machine', 'cleanup:delete_machine', cleanup=True, stateMachineArn=ARNS[machine])
    missing = set()
    for attempt in range(40):
        for machine in CREATED['machines']:
            if machine in missing: continue
            record = call('stepfunctions', 'describe_state_machine', 'cleanup:verify_machine_absent', cleanup=True, stateMachineArn=ARNS[machine])
            if record.get('error', {}).get('Error', {}).get('Code') == 'StateMachineDoesNotExist': missing.add(machine)
        if len(missing) == len(CREATED['machines']): break
        time.sleep(3)
    if CREATED['bucket']:
        objects = call('s3', 'list_objects_v2', 'cleanup:list_objects', cleanup=True, Bucket=BUCKET)
        keys = [item['Key'] for item in objects.get('response', {}).get('Contents', [])]
        if keys: call('s3', 'delete_objects', 'cleanup:delete_objects', cleanup=True, Bucket=BUCKET, Delete={'Objects': [{'Key': key} for key in keys], 'Quiet': False})
        call('s3', 'delete_bucket', 'cleanup:delete_bucket', cleanup=True, Bucket=BUCKET)
        call('s3', 'head_bucket', 'cleanup:verify_bucket_absent', cleanup=True, Bucket=BUCKET)
    if CREATED['role']:
        call('iam', 'delete_role_policy', 'cleanup:delete_policy', cleanup=True, RoleName=ROLE, PolicyName='owned-map-access')
        call('iam', 'delete_role', 'cleanup:delete_role', cleanup=True, RoleName=ROLE)
        call('iam', 'get_role', 'cleanup:verify_role_absent', cleanup=True, RoleName=ROLE)
    DATA['cleanup_machine_absence_verified'] = sorted(missing)
    DATA['execution_count_observed'] = {'parents': len(PARENTS), 'children': len(CHILDREN), 'total': len(PARENTS) + len(CHILDREN)}
    DATA['finished_at'] = datetime.now(timezone.utc).isoformat()
    save()

try:
    DATA['cli_identity'] = observe('sts', 'get-caller-identity', {}, ENV)
    if DATA['cli_identity'].get('output', {}).get('Account') != ACCOUNT: raise RuntimeError('Refusing unexpected AWS account')
    required(call('sts', 'get_caller_identity', 'preflight:identity'))
    for name, definition in DEFINITIONS.items():
        check = required(call('stepfunctions', 'validate_state_machine_definition', 'preflight:validate:' + name, definition=json.dumps(definition), type='STANDARD', severity='WARNING'))
        if check['result'] != 'OK': raise RuntimeError('Native definition validation failed: ' + name)
    trust = {'Version': '2012-10-17', 'Statement': [{'Effect': 'Allow', 'Principal': {'Service': 'states.amazonaws.com'}, 'Action': 'sts:AssumeRole', 'Condition': {'StringEquals': {'aws:SourceAccount': ACCOUNT}, 'ArnLike': {'aws:SourceArn': f'arn:aws:states:{REGION}:{ACCOUNT}:stateMachine:{PREFIX}-*'}}}]}
    required(call('iam', 'create_role', 'setup:role', RoleName=ROLE, AssumeRolePolicyDocument=json.dumps(trust)))
    CREATED['role'] = True
    policy = {'Version': '2012-10-17', 'Statement': [
        {'Effect': 'Allow', 'Action': ['states:StartExecution'], 'Resource': [f'arn:aws:states:{REGION}:{ACCOUNT}:stateMachine:{PREFIX}-*']},
        {'Effect': 'Allow', 'Action': ['states:DescribeExecution', 'states:StopExecution'], 'Resource': [f'arn:aws:states:{REGION}:{ACCOUNT}:execution:{PREFIX}-*:*']},
        {'Effect': 'Allow', 'Action': ['s3:GetObject', 's3:PutObject'], 'Resource': [f'arn:aws:s3:::{BUCKET}/*']},
        {'Effect': 'Allow', 'Action': ['s3:ListBucket'], 'Resource': [f'arn:aws:s3:::{BUCKET}']}]}
    required(call('iam', 'put_role_policy', 'setup:policy', RoleName=ROLE, PolicyName='owned-map-access', PolicyDocument=json.dumps(policy)))
    required(call('s3', 'create_bucket', 'setup:bucket', Bucket=BUCKET, CreateBucketConfiguration={'LocationConstraint': REGION}))
    CREATED['bucket'] = True
    objects = {
        'inputs/nested.json': b'{"data":{"items":[{"n":0,"text":"zero"},{"n":1,"text":"one"},{"n":2,"text":"two"},{"n":3,"text":"three"},{"n":4,"text":"excluded"}]}}\n',
        'inputs/data.csv': b'id|text|blank\r\n1|"one|pipe"|\r\n2|"two ""quoted"""|x\r\n3|"three\nnewline"|y\r\n4|four|\r\n5|excluded|z\r\n',
        'flat/data.jsonl': b'{"n":10}\n{"n":11}\n{"n":12}\n'}
    for key, body in objects.items(): required(call('s3', 'put_object', 'setup:input', Bucket=BUCKET, Key=key, Body=body))
    time.sleep(12)
    for name, definition in DEFINITIONS.items():
        created = call('stepfunctions', 'create_state_machine', 'setup:machine:' + name, name=PREFIX + '-' + name, definition=json.dumps(definition), roleArn=ROLE_ARN, type='STANDARD')
        required(created)
        CREATED['machines'].append(name)
    run_case('cancel_pending', 'lifecycle', {'items': [{'n': i, 'wait': 25 if i == 0 else 0, 'fail': i == 0} for i in range(4)], 'concurrency': 1, 'tolerance': 0, 'prefix': 'results/cancel'}, 5, initial_detail=True)
    run_case('tolerated_failure', 'lifecycle', {'items': [{'n': i, 'wait': 4, 'fail': i == 0} for i in range(4)], 'concurrency': 2, 'tolerance': 1, 'prefix': 'results/tolerance'}, 5)
    run_case('json_pointer_batch', 'readers', {'kind': 'json', 'tag': 'json-batch'}, 3, initial_detail=True)
    run_case('csv_pipe_batch', 'readers', {'kind': 'csv', 'tag': 'csv-batch'}, 3)
    run_case('jsonata_flatten', 'sources', {'kind': 'flatten', 'items': [10, 20]}, 3)
    run_case('s3_metadata', 'sources', {'kind': 'metadata'}, 2)
    run_case('s3_load_flatten', 'sources', {'kind': 'load'}, 2)
except Exception as exc:
    DATA['fatal'] = {'type': type(exc).__name__, 'message': str(exc), 'traceback': traceback.format_exc()}
    save()
    print(json.dumps(DATA['fatal']), flush=True)
finally:
    cleanup()
print(json.dumps({'fixture': str(OUT), 'prefix': PREFIX, 'execution_count_observed': DATA.get('execution_count_observed'), 'fatal': DATA.get('fatal'), 'cleanup_terminal': DATA.get('cleanup_all_executions_terminal'), 'machine_absence': DATA.get('cleanup_machine_absence_verified')}), flush=True)

"""AWS CLI transport shared by native behavior probes.

Callers own endpoint/retry choices, observations and resource cleanup. JSON shapes
remain open because probes deliberately exercise invalid and newly added inputs.
"""
import ast
import json
import re
import subprocess
from collections.abc import Mapping, Sequence
from typing import Any, NotRequired, TypedDict


class ProbeResult(TypedDict):
    code: str
    output: NotRequired[dict[str, Any]]
    error: NotRequired[dict[str, Any]]
    message: NotRequired[str]
    http_status: NotRequired[int]


class CLITimeout(RuntimeError):
    """A bounded CLI call expired; command arguments may contain secrets."""


class AWSCLIError(RuntimeError):
    """A failed strict call, retaining native JSON error fields for its caller."""

    def __init__(self, service: str, operation: str, stderr: str, details: dict[str, Any]):
        super().__init__(f"{service}:{operation}: {stderr.strip()}")
        self.details = details


def run(service: str, operation: str, parameters: Mapping[str, Any] | None = None,
        env: Mapping[str, str] | None = None, *, options: Sequence[str] = (),
        timeout: float | None = None) -> subprocess.CompletedProcess[str]:
    """Execute one CLI command without interpreting service or client failures."""
    command = ["aws", service, operation, "--output", "json", "--no-cli-pager"]
    if parameters is not None:
        command += ["--cli-input-json", json.dumps(parameters)]
    try:
        return subprocess.run(command + list(options), env=env, capture_output=True,
                              text=True, check=False, timeout=timeout)
    except subprocess.TimeoutExpired:
        raise CLITimeout("AWS CLI timed out during " + operation) from None


def call(service: str, operation: str, parameters: Mapping[str, Any] | None = None,
         env: Mapping[str, str] | None = None, *, paginate: bool = True,
         error_format: str | None = None) -> dict[str, Any]:
    """Return JSON output; service and CLI-validation errors retain typed details.

    Configuration and transport failures abort capture instead of becoming
    observations of AWS behavior. AWS CLI uses 252 for input errors and 254
    for service errors.
    """
    options = ["--cli-connect-timeout", "10", "--cli-read-timeout", "30"]
    if error_format is not None:
        options += ["--cli-error-format", error_format]
    if not paginate:
        options.append("--no-paginate")
    process = run(service, operation, parameters or None, env, options=options)
    if process.returncode:
        diagnosis = f"{service}:{operation}: {process.stderr.strip()}"
        if error_format == "json" and process.returncode in (252, 254):
            try:
                details = json.loads(process.stderr)
            except json.JSONDecodeError:
                raise RuntimeError(diagnosis) from None
            if isinstance(details, dict) and isinstance(details.get("Code"), str):
                raise AWSCLIError(service, operation, process.stderr, details)
        raise RuntimeError(diagnosis)
    return result(process)["output"]


def observe(service: str, operation: str, parameters: Mapping[str, Any] | None = None,
            env: Mapping[str, str] | None = None, *, paginate: bool = True) -> ProbeResult:
    """Capture native JSON success/error fields; callers own output redaction."""
    try:
        output = call(service, operation, parameters, env, paginate=paginate, error_format="json")
    except AWSCLIError as error:
        return {"code": error.details["Code"], "error": error.details}
    return {"code": "Success", "output": output}


def _text_error(stderr: str) -> tuple[str, str | None]:
    match = re.search(r"An error occurred \(([^)]+)\)(?:.*?operation(?: \([^)]*\))?: (.*))?", stderr)
    return (match[1], match[2]) if match else ("CLIError", None)


def result(process: subprocess.CompletedProcess[str], *, cli_error: str = "CLIError",
           cli_message: str | None = "AWS CLI failed; raw diagnostics discarded",
           debug: bool = False) -> ProbeResult:
    """Decode an observation, separating modeled errors from CLI rejection.

    A None client message retains the final three diagnostic lines for probes
    whose captured CLI-validation observations include those lines.
    """
    if process.returncode:
        code, message = _text_error(process.stderr)
        decoded: ProbeResult = {
            "code": code if message is not None else cli_error,
            "message": message if message is not None else cli_message if cli_message is not None
            else " ".join(process.stderr.splitlines()[-3:]),
        }
    else:
        decoded = {"code": "Success", "output": json.loads(process.stdout) if process.stdout.strip() else {}}
    if debug:
        statuses = re.findall(r'"[A-Z]+ [^"\r\n]* HTTP/1\.[01]" (\d{3})', process.stderr)
        if statuses:
            decoded["http_status"] = int(statuses[-1])
    return decoded


def error_code(process: subprocess.CompletedProcess[str]) -> str:
    """Decode code-only observations, including CLI ParamValidation errors."""
    return _text_error(process.stderr)[0]


def raw_xml(process: subprocess.CompletedProcess[str]) -> bytes | None:
    """Extract the last XML response from CLI debug output; discard other logs."""
    raw = None
    for line in process.stderr.splitlines():
        if line.startswith(("b'<", 'b"<')):
            try:
                candidate = ast.literal_eval(line)
                if candidate.startswith(b"<"):
                    raw = candidate
            except (ValueError, SyntaxError):
                pass
    return raw

